const D = { energy: .6, scale: 1, speed: 1, density: .5, shear: .35, hue: 40, x: .5, y: .80, style: 'euv_gold', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Coronal rain over an arcade -----------------------------------------------------------
// An arcade of magnetic loops standing off the limb, each rooted at both feet in the
// photosphere and filled with million-degree plasma that glows in the extreme ultraviolet.
// A loop that is heated near its feet piles up too much mass at its top to stay hot; the
// balance fails, the apex CATASTROPHICALLY COOLS in minutes, and the plasma there condenses
// into blobs a hundred times denser and cooler than the corona around them. They cannot fall
// straight down — they are charged, and charged matter is threaded on the field — so they
// drain along the loop instead, and that is the whole beauty of it: the gravity a blob feels
// is only the component along its own field line, which is ZERO at the apex and full at the
// footpoint. So it hangs at the top, creeps, and then plunges into the leg. That is integrated
// here, not faked: each drop carries a true speed along the arc, ds/du and dy/du come from the
// loop's own geometry, and the drop drains to whichever side of the apex it happened to
// condense on. Drops respawn forever, so the arcade never empties and never settles.
// The loops themselves ring in the transverse kink mode, each at its own incommensurate rate.
// --------------------------------------------------------------------------------------------

const TAU = 6.283185307;
const PI = Math.PI;
const style = P.style;
const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
const fr2 = (i, j) => { const s = Math.sin(i * 127.1 + j * 311.7 + sd * 74.77) * 43758.5453; return s - Math.floor(s); };

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dtr = K.t - S.lastT; S.lastT = K.t;
dtr = dtr < 0 ? 0 : (dtr > 0.06 ? 0.06 : dtr);
if (S.T == null) S.T = 0;
const spd = 0.25 + P.speed * 0.9;
S.T += dtr * spd;
const ts = S.T, dt = dtr * spd;

const en = Math.min(1, Math.max(0, P.energy));
const scl = Math.max(0.4, P.scale);
const dens = Math.min(1, Math.max(0, P.density));
const limbY = Math.min(0.98, Math.max(0.45, P.y)) * height;
const arcX = Math.min(1, Math.max(0, P.x)) * width;
const shearA = (P.shear - 0.5) * 1.5;

// incommensurate real-time floor
const dr1 = Math.sin(K.t * 0.061) * 0.9 + Math.sin(K.t * 0.143 + 1.7) * 0.5 + Math.sin(K.t * 0.229) * 0.32;
const dr2 = Math.sin(K.t * 0.077 + 2.1) * 0.8 + Math.sin(K.t * 0.181 + 0.4) * 0.44;

const h2rgb = (h, s, v) => {
  h = (((h % 360) + 360) % 360) / 60;
  const c = v * s, x = c * (1 - Math.abs(h % 2 - 1)), m = v - c;
  if (h < 1) return [c + m, x + m, m];
  if (h < 2) return [x + m, c + m, m];
  if (h < 3) return [m, c + m, x + m];
  if (h < 4) return [m, x + m, c + m];
  if (h < 5) return [x + m, m, c + m];
  return [c + m, m, x + m];
};

// ---- the arcade ---------------------------------------------------------------------------
const NL = Math.round(5 + dens * 13);
if (!S.LX || S.LX.length < 24) { S.LX = new Float64Array(24); S.LRX = new Float64Array(24); S.LRY = new Float64Array(24); S.LRO = new Float64Array(24); S.LKK = new Float64Array(24); S.LDZ = new Float64Array(24); }
const LX = S.LX, LRX = S.LRX, LRY = S.LRY, LRO = S.LRO, LKK = S.LKK, LDZ = S.LDZ;
const spread = (0.30 + dens * 0.42) * scl;
for (let li = 0; li < NL; li++) {
  const f1 = fr(li * 3.1 + 1.7), f2 = fr(li * 7.7 + 5.3), f3 = fr(li * 11.3 + 9.1), f4 = fr(li * 5.1 + 13.7);
  const dz = 0.40 + f1 * 0.60;                                   // depth rank: far loops small + hazed
  LDZ[li] = dz;
  LX[li] = arcX + ((NL < 2 ? 0.5 : li / (NL - 1)) - 0.5) * spread * width + (f2 - 0.5) * 0.05 * width
         + 0.024 * width * Math.sin(ts * 0.051 + f1 * TAU) + 0.014 * width * Math.sin(ts * 0.113 + f3 * TAU);
  LRX[li] = (0.045 + f3 * 0.115) * scl * width * dz;
  LRY[li] = (0.11 + f4 * 0.44 + en * 0.16) * scl * height * dz * (1 + 0.13 * Math.sin(ts * (0.083 + f4 * 0.071) + f2 * TAU));
  LRO[li] = shearA * ((NL < 2 ? 0.5 : li / (NL - 1)) - 0.5) + (f2 - 0.5) * 0.20;
  // transverse kink mode: each loop rings at its own rate, so the arcade never re-phases
  LKK[li] = 0.034 * width * dz * (0.4 + en) * Math.sin(ts * (0.29 + f3 * 0.31) + f1 * TAU);
}
// point on loop li at u in [0,1]; also its d(arc)/du and d(height)/du
const lpt = (li, u) => {
  const a = PI * u, ro = LRO[li], cr = Math.cos(ro), sr = Math.sin(ro);
  const lx = LRX[li] * Math.cos(a) + LKK[li] * Math.sin(a);
  const ly = LRY[li] * Math.sin(a);                                // local height, up
  return [LX[li] + lx * cr - ly * sr, limbY - (ly * cr + lx * sr)];
};
const lder = (li, u) => {
  const a = PI * u, ro = LRO[li], cr = Math.cos(ro), sr = Math.sin(ro);
  const dlx = -PI * LRX[li] * Math.sin(a) + PI * LKK[li] * Math.cos(a);
  const dly = PI * LRY[li] * Math.cos(a);
  const dwx = dlx * cr - dly * sr, dwy = dly * cr + dlx * sr;      // dwy = d(height)/du, up
  return [Math.sqrt(dwx * dwx + dwy * dwy), dwy];
};

// ---- coarse glow field: splat the loops in, then upscale (the cheap volumetric trick) ------
const BW = 168, BH = Math.max(56, Math.round(BW * height / width));
if (!S.g || S.key !== width + 'x' + height) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.key = width + 'x' + height;
  S.FL = new Float32Array(BW * BH); S.HZ = new Float32Array(BW * BH); S.hzKey = null;
}
const g = S.g, FL = S.FL, HZ = S.HZ;
const bsx = BW / width, bsy = BH / height;

if (S.hzKey !== S.key + ':' + sd) {                                // static plate grain
  S.hzKey = S.key + ':' + sd;
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) HZ[j * BW + i] = fr2(i * 2.7 + 1.3, j * 5.1 + 7.9);
}
FL.fill(0);
const splat = (bx, by, rad, amp) => {
  const x0 = Math.max(0, Math.floor(bx - rad)), x1 = Math.min(BW - 1, Math.ceil(bx + rad));
  const y0 = Math.max(0, Math.floor(by - rad)), y1 = Math.min(BH - 1, Math.ceil(by + rad));
  const ir2 = 1 / (rad * rad * 0.42);
  for (let y = y0; y <= y1; y++) { const dy = y - by; for (let x = x0; x <= x1; x++) { const dx = x - bx, q = (dx * dx + dy * dy) * ir2; if (q < 7) FL[y * BW + x] += amp * Math.exp(-q); } }
};
const NU = 48;
for (let li = 0; li < NL; li++) {
  const dz = LDZ[li];
  const rad = (1.5 + 2.6 * dz) * scl;
  const amp = (0.030 + en * 0.045) * (0.35 + dz * 0.85);
  for (let k = 0; k <= NU; k++) {
    const u = k / NU, pq = lpt(li, u);
    // loops are brightest at their feet, where the heating is
    const foot = 1 + 1.5 * Math.exp(-u * u * 26) + 1.5 * Math.exp(-(1 - u) * (1 - u) * 26);
    splat(pq[0] * bsx, pq[1] * bsy, rad, amp * foot);
  }
}
// the limb itself, and the diffuse corona that sits over the whole active region
for (let i = 0; i < BW; i++) splat(i, limbY * bsy, 4.5 * scl, 0.052 + en * 0.030);
splat(arcX * bsx, (limbY - 0.10 * height) * bsy, BH * 0.55, (0.030 + en * 0.028) * (1 + 0.16 * Math.sin(K.t * 0.071)));

// ---- palettes ----
let sky, cLo, cMi, cHi, rainC;
if (style === 'euv_teal') { sky = [0.012, 0.030, 0.034]; cLo = h2rgb(178, 0.95, 0.30); cMi = h2rgb(166, 0.80, 0.72); cHi = h2rgb(150, 0.16, 1.0); rainC = h2rgb(52, 0.72, 1.0); }
else if (style === 'halpha') { sky = [0.030, 0.014, 0.020]; cLo = h2rgb(P.hue - 32, 0.94, 0.26); cMi = h2rgb(P.hue - 26, 0.86, 0.66); cHi = h2rgb(P.hue - 10, 0.30, 1.0); rainC = h2rgb(P.hue - 34, 0.95, 0.90); }
else if (style === 'schematic') { sky = [0.030, 0.042, 0.066]; cLo = h2rgb(196, 0.72, 0.34); cMi = h2rgb(192, 0.60, 0.62); cHi = h2rgb(188, 0.22, 0.92); rainC = [1.0, 0.96, 0.86]; }
else if (style === 'xray') { sky = [0.028, 0.028, 0.030]; cLo = [0.20, 0.20, 0.21]; cMi = [0.56, 0.56, 0.56]; cHi = [0.98, 0.98, 0.97]; rainC = [0.06, 0.06, 0.07]; }
else { sky = [0.030, 0.020, 0.012]; cLo = h2rgb(P.hue - 16, 0.96, 0.28); cMi = h2rgb(P.hue, 0.82, 0.70); cHi = h2rgb(P.hue + 16, 0.16, 1.0); rainC = h2rgb(P.hue - 32, 0.90, 0.95); }

// value noise -> fbm, for the diffuse corona and the moss on the disk
const vn = (x, y) => {
  const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi;
  const ux = xf * xf * (3 - 2 * xf), uy = yf * yf * (3 - 2 * yf);
  const a = fr2(xi, yi), b = fr2(xi + 1, yi), c = fr2(xi, yi + 1), d = fr2(xi + 1, yi + 1);
  return (a * (1 - ux) + b * ux) * (1 - uy) + (c * (1 - ux) + d * ux) * uy;
};
const fbm = (x, y) => vn(x, y) * 0.55 + vn(x * 2.03 + 11.3, y * 2.03 + 5.7) * 0.29 + vn(x * 4.11 + 3.9, y * 4.11 + 17.1) * 0.16;

g.loadPixels();
const gp = g.pixels;
const gam = style === 'schematic' ? 1.5 : 1.0;
const lF = limbY / height, aF = arcX / width;
const diskK = style === 'schematic' ? 0.10 : (style === 'xray' ? 0.42 : 1.0);
const hazeK = style === 'schematic' ? 0.42 : (style === 'xray' ? 0.72 : 1.0);
for (let p = 0; p < BW * BH; p++) {
  const bi = p % BW, bj = (p - bi) / BW;
  const fx = (bi + 0.5) / BW, fy = (bj + 0.5) / BH;
  let v = FL[p];
  v = 1 - Math.exp(-v * (1.5 + en * 1.1));                         // saturating, so the feet don't blow out
  if (gam !== 1) v = Math.pow(v, gam);

  // the diffuse corona — an active region is never sitting on black, it sits in its own halo,
  // and that halo is turbulent, so it drifts and is the frame's broadest moving element
  const hz = fbm(fx * 3.4 + ts * 0.032 + dr1 * 0.05, fy * 3.4 - ts * 0.021);
  const hz2 = fbm(fx * 8.5 - ts * 0.045, fy * 8.5 + ts * 0.028 + dr2 * 0.04);
  const above = Math.max(0, lF - fy);
  const halo = Math.exp(-Math.pow((fx - aF) / 0.60, 2));
  const diffuse = (0.060 + 0.40 * hz + 0.15 * hz2) * Math.exp(-above / 0.62)
                * (0.46 + 0.54 * halo) * (0.60 + en * 0.62) * hazeK;
  v = v + diffuse * (1 - v);

  // below the limb: the disk itself, carpeted in EUV moss at the feet of everything above
  if (fy > lF) {
    const dd = (fy - lF) / Math.max(0.02, 1 - lF);
    const moss = 0.40 + 0.44 * fbm(fx * 13.0 + ts * 0.042, fy * 30.0 - ts * 0.030) + 0.16 * (hz2 - 0.5);
    const dv = moss * Math.min(1, dd * 7 + 0.30) * (0.6 + en * 0.5) * diskK;
    v = v + dv * (1 - v);
  }

  v += (HZ[p] - 0.5) * 0.035;
  v = v < 0 ? 0 : (v > 1 ? 1 : v);
  let R, G2, B;
  if (v < 0.30) { const u = v / 0.30; R = sky[0] + (cLo[0] - sky[0]) * u; G2 = sky[1] + (cLo[1] - sky[1]) * u; B = sky[2] + (cLo[2] - sky[2]) * u; }
  else if (v < 0.68) { const u = (v - 0.30) / 0.38; R = cLo[0] + (cMi[0] - cLo[0]) * u; G2 = cLo[1] + (cMi[1] - cLo[1]) * u; B = cLo[2] + (cMi[2] - cLo[2]) * u; }
  else { const u = (v - 0.68) / 0.32; R = cMi[0] + (cHi[0] - cMi[0]) * u; G2 = cMi[1] + (cHi[1] - cMi[1]) * u; B = cMi[2] + (cHi[2] - cMi[2]) * u; }
  const o = 4 * p;
  gp[o] = R < 0 ? 0 : (R > 1 ? 255 : R * 255);
  gp[o + 1] = G2 < 0 ? 0 : (G2 > 1 ? 255 : G2 * 255);
  gp[o + 2] = B < 0 ? 0 : (B > 1 ? 255 : B * 255);
  gp[o + 3] = 255;
}
g.updatePixels();
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

const aMul = P.alpha / 100;
const css = (c, a) => 'rgba(' + Math.round(Math.min(255, c[0] * 255)) + ',' + Math.round(Math.min(255, c[1] * 255)) + ',' + Math.round(Math.min(255, c[2] * 255)) + ',' + Math.min(1, Math.max(0, a)).toFixed(3) + ')';

// ---- sharp loop cores at full res ----------------------------------------------------------
push();
if (style !== 'xray') blendMode(ADD);
noFill();
for (let li = 0; li < NL; li++) {
  const dz = LDZ[li];
  strokeWeight(Math.max(0.6, (0.8 + dz * 1.9) * scl));
  const cc = style === 'xray' ? [0.02, 0.02, 0.03] : cHi;
  drawingContext.strokeStyle = css(cc, (0.10 + dz * 0.24) * (0.4 + en * 0.8) * aMul);
  stroke(0, 0, 100, 1);
  beginShape();
  for (let k = 0; k <= NU; k++) { const q = lpt(li, k / NU); vertex(q[0], q[1]); }
  endShape();
}
pop();

// ---- the rain -------------------------------------------------------------------------------
const NDMAX = 220;
const ND = Math.min(NDMAX, Math.round(40 + dens * 140 + en * 40));
if (!S.RU || S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.RU = new Float64Array(NDMAX); S.RV = new Float64Array(NDMAX); S.RL = new Int32Array(NDMAX);
  S.RA = new Float64Array(NDMAX); S.RM = new Float64Array(NDMAX); S.rc = 0;
  for (let d = 0; d < NDMAX; d++) S.RA[d] = -1;
}
const RU = S.RU, RV = S.RV, RL = S.RL, RA = S.RA, RM = S.RM;
const gAcc = (0.55 + en * 1.35) * 0.30;                            // gravity along the field line
const spawn = d => {
  const c = (S.rc = (S.rc + 1) % 100000);
  RL[d] = Math.floor(fr(c * 1.7 + 3.3) * NL) % Math.max(1, NL);
  RU[d] = 0.5 + (fr(c * 5.9 + 11.1) - 0.5) * 0.40;                 // condenses near the apex, either side
  RV[d] = (fr(c * 3.1 + 7.7) - 0.5) * 0.006;
  RA[d] = 0;
  RM[d] = 0.5 + fr(c * 9.3 + 2.1) * 0.9;                           // blob mass -> size + brightness
};
push();
if (style !== 'xray') blendMode(ADD);
noStroke();
for (let d = 0; d < ND; d++) {
  if (RA[d] < 0) { spawn(d); RA[d] = fr(d * 13.1 + 5) * 6; }       // stagger the first fill
  RA[d] += dt;
  const li = RL[d];
  if (li >= NL) { spawn(d); continue; }
  // integrate ALONG THE ARC: a_s = -g * (dy/du)/(ds/du) — zero at the apex, full at the foot
  const dv = lder(li, RU[d]);
  const dsdu = Math.max(1e-6, dv[0]);
  const aS = -gAcc * (dv[1] / dsdu) * width;
  RV[d] += aS * dt / width;
  RV[d] *= 1 - Math.min(0.4, 0.55 * dt);                            // a little drag
  RU[d] += (RV[d] / dsdu) * width * dt;
  if (RU[d] <= 0.004 || RU[d] >= 0.996 || RA[d] > 90) { spawn(d); continue; }

  const q = lpt(li, RU[d]);
  const dz = LDZ[li];
  const cond = Math.min(1, RA[d] * 0.85);                           // it takes a moment to condense
  const foot = Math.min(1, Math.min(RU[d], 1 - RU[d]) / 0.06);      // swallowed at the footpoint
  const br = cond * foot * (0.45 + en * 0.75) * (0.35 + dz * 0.8) * RM[d];
  const rr = (0.0050 + RM[d] * 0.0060) * scl * Math.min(width, height) * dz;
  if (br < 0.02) continue;

  // a tail, dragged back up the field line the way it came
  const sp = Math.abs(RV[d]);
  const tl = Math.min(0.10, sp * 1.9);
  if (tl > 0.004) {
    const back = RU[d] - Math.sign(RV[d]) * tl;
    const qb = lpt(li, Math.min(0.999, Math.max(0.001, back)));
    drawingContext.fillStyle = css(rainC, 0.20 * br * aMul);
    const dxq = q[0] - qb[0], dyq = q[1] - qb[1], Lq = Math.hypot(dxq, dyq) || 1;
    const nx = -dyq / Lq * rr * 0.85, ny = dxq / Lq * rr * 0.85;
    beginShape();
    vertex(q[0] + nx, q[1] + ny); vertex(q[0] - nx, q[1] - ny); vertex(qb[0], qb[1]);
    endShape(CLOSE);
  }
  drawingContext.fillStyle = css(rainC, Math.min(1, 0.62 * br) * aMul);
  fill(0, 0, 100, 1);
  ellipse(q[0], q[1], rr * 2, rr * 2);
  // where it lands, the leg lights up
  if (RU[d] < 0.10 || RU[d] > 0.90) {
    drawingContext.fillStyle = css(cHi, 0.10 * br * (1 - foot) * aMul);
    ellipse(q[0], q[1], rr * 9, rr * 9);
  }
}
pop();

// audio adds on top of a baseline that already carries itself
if (A.rms > 0.01) {
  push(); blendMode(ADD); noStroke();
  drawingContext.fillStyle = css(cHi, Math.min(0.16, A.bass * 0.13 + K.pulse * 0.03) * aMul);
  ellipse(arcX, limbY, width * 1.1, height * 0.55);
  pop();
}

blendMode(BLEND);
drawingContext.shadowBlur = 0;
